const cities = [
  { name: 'London', lat: 51.51, lon: -0.13 },
  { name: 'Tokyo', lat: 35.68, lon: 139.69 },
  { name: 'Sydney', lat: -33.87, lon: 151.21 },
];

// Tiny bundled fallback so the notebook works offline too.
const FALLBACK = cities.map((c, ci) => ({
  name: c.name,
  time: Array.from({ length: 48 }, (_, h) => '2026-01-01T' + String(h % 24).padStart(2, '0') + ':00'),
  temps: Array.from({ length: 48 }, (_, h) =>
    +(12 + ci * 6 + 7 * Math.sin((h - 14) / 24 * 2 * Math.PI)).toFixed(1)),
}));

let weather = [];
let live = true;
try {
  for (const c of cities) {
    const url = 'https://api.open-meteo.com/v1/forecast' +
      '?latitude=' + c.lat + '&longitude=' + c.lon +
      '&hourly=temperature_2m&forecast_days=2&timezone=UTC';
    const res = await fetch(url);
    if (!res.ok) throw new Error('HTTP ' + res.status + ' for ' + c.name);
    const data = await res.json();
    weather.push({
      name: c.name,
      time: data.hourly.time,
      temps: data.hourly.temperature_2m,
    });
    console.log(c.name + ': ' + data.hourly.time.length + ' hourly readings');
  }
} catch (err) {
  console.warn('live fetch failed (' + err.message + ') - using bundled sample data');
  weather = FALLBACK;
  live = false;
}

nb.set('weather', weather);
nb.set('weather_live', live);
console.log(live ? 'live data published as weather' : 'sample data published as weather');

// One chart, three cities: long-format rows + a colour encoding.
const weather = nb.get('weather');
if (!weather) return 'Run the fetch cell first.';

const rows = [];
for (const city of weather) {
  city.temps.forEach((t, i) => {
    rows.push({ time: city.time[i], temp: t, city: city.name });
  });
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 320,
  title: 'Hourly temperature, next 48 h (' + (nb.get('weather_live') ? 'live Open-Meteo data' : 'bundled sample') + ')',
  data: { values: rows },
  mark: { type: 'line', interpolate: 'monotone' },
  encoding: {
    x: { field: 'time', type: 'temporal', title: 'UTC time' },
    y: { field: 'temp', type: 'quantitative', title: 'temperature C', scale: { zero: false } },
    color: { field: 'city', type: 'nominal' },
  },
};
